using System;using System.Collections.Generic;using System.Drawing;using System.Linq;using System.Windows.Forms;
namespace IDSketcher {
static class ArcAssist {
 // Endpoints constrain the circle; all interior samples estimate its centre.
 public static List<PointF> Fit(List<PointF> p){if(p.Count<5)return null;var a=p[0];var b=p[p.Count-1];double dx=b.X-a.X,dy=b.Y-a.Y,chord=Math.Sqrt(dx*dx+dy*dy);if(chord<5)return null;double mx=(a.X+b.X)/2,my=(a.Y+b.Y)/2,nx=-dy/chord,ny=dx/chord,numerator=0,denominator=0;foreach(var q in p){double x=q.X-mx,y=q.Y-my,v=x*nx+y*ny,k=x*x+y*y-chord*chord/4;numerator+=v*k;denominator+=2*v*v;}if(denominator<1e-5)return null;double offset=numerator/denominator,cx=mx+nx*offset,cy=my+ny*offset,r=Math.Sqrt(chord*chord/4+offset*offset);if(r>chord*20)return null;double error=0,start=Math.Atan2(a.Y-cy,a.X-cx),last=start,turn=0;foreach(var q in p){double x=q.X-cx,y=q.Y-cy;error+=Math.Pow(Math.Sqrt(x*x+y*y)-r,2);double angle=Math.Atan2(y,x),delta=angle-last;while(delta>Math.PI)delta-=2*Math.PI;while(delta< -Math.PI)delta+=2*Math.PI;turn+=delta;last=angle;}if(Math.Sqrt(error/p.Count)>Math.Max(3,r*.15)||Math.Abs(turn)<.15||Math.Abs(turn)>Math.PI*2)return null;int count=Math.Max(12,Math.Min(8000,(int)Math.Ceiling(r*Math.Abs(turn)/2)));var result=new List<PointF>();for(int i=0;i<=count;i++){double angle=start+turn*i/count;result.Add(new PointF((float)(cx+r*Math.Cos(angle)),(float)(cy+r*Math.Sin(angle))));}result[0]=a;result[result.Count-1]=b;return result;}
 public static List<PointF> Simplify(List<PointF> points,float tolerance){if(points.Count<3)return new List<PointF>(points);var keep=new bool[points.Count];keep[0]=keep[points.Count-1]=true;var pending=new Stack<int[]>();pending.Push(new[]{0,points.Count-1});while(pending.Count>0){var pair=pending.Pop();var a=points[pair[0]];var b=points[pair[1]];float dx=b.X-a.X,dy=b.Y-a.Y,len=dx*dx+dy*dy,best=tolerance*tolerance;int index=-1;for(int i=pair[0]+1;i<pair[1];i++){var p=points[i];float t=len==0?0:Math.Max(0,Math.Min(1,((p.X-a.X)*dx+(p.Y-a.Y)*dy)/len)),x=p.X-a.X-t*dx,y=p.Y-a.Y-t*dy,d=x*x+y*y;if(d>best){best=d;index=i;}}if(index>=0){keep[index]=true;pending.Push(new[]{pair[0],index});pending.Push(new[]{index,pair[1]});}}return points.Where((p,i)=>keep[i]).ToList();}
}
partial class StrokeSession {
 public bool FitArc(){var fit=ArcAssist.Fit(points);if(fit==null)return false;var samples=pressures.ToArray();points.Clear();pressures.Clear();points.Add(fit[0]);pressures.Add(samples[0]);length=0;brush.Reset(fit[0],size*(hardware?PressureScale(samples[0]):pressure?TipScale:1));for(int i=1;i<fit.Count;i++){float t=(float)i/(fit.Count-1)*(samples.Length-1);int lo=(int)t,hi=Math.Min(samples.Length-1,lo+1);HardwarePressure=samples[lo]+(samples[hi]-samples[lo])*(t-lo);Move(fit[i]);}return true;}
}
partial class Canvas {
 bool arcStroke;Keys freehandModifiers;List<PointF> freehandPoints;
 void StartVectorFreehand(PointF p,Keys modifiers){freehandModifiers=modifiers;freehandPoints=new List<PointF>{p};draft=new VectorShape{Kind="Curvature pen",Colour=Ink,Width=VectorWidth,Opacity=VectorOpacity,Taper=VectorTaper,Fill=VectorFill.Copy()};draft.Points.Add(p);vectorDragging=true;Capture=true;Invalidate();}
 void MoveVectorFreehand(PointF p){if(freehandPoints==null)return;UpdateFreehandModifiers(ModifierKeys);if(StrokeSession.Distance(freehandPoints.Last(),p)*Zoom<1)return;freehandPoints.Add(p);if(freehandPoints.Count>8000)freehandPoints=freehandPoints.Where((q,i)=>i%2==0||i==freehandPoints.Count-1).ToList();draft.Points=(freehandModifiers&Keys.Shift)!=0?new List<PointF>{freehandPoints[0],p}:new List<PointF>(freehandPoints);InvalidateVectorArea(draft.Bounds());}
 void FinishVectorFreehand(PointF p){MoveVectorFreehand(p);if(StrokeSession.Distance(freehandPoints.Last(),p)>.001f)freehandPoints.Add(p);var points=freehandPoints;if((freehandModifiers&Keys.Shift)!=0){draft.Kind="Line";draft.Points=new List<PointF>{points[0],p};}else if((freehandModifiers&Keys.Control)!=0){var fit=FittedEllipse.Fit(points);if(fit!=null){draft.Kind="Ellipse";draft.Points=new List<PointF>{fit.Centre,fit.At(0),fit.At(Math.PI/2)};}else draft.Points=ProportionalPoints(points,FreehandSpacing);}else if((freehandModifiers&Keys.Alt)==0||!FitVectorArc(draft,points,FreehandSpacing))draft.Points=ProportionalPoints(points,FreehandSpacing);freehandPoints=null;vectorDragging=false;Capture=false;if(draft!=null&&draft.Points.Count>=2)FinishVector();else draft=null;Invalidate();}
 public void TestFreehand(List<PointF> points,Keys modifiers){StartVectorFreehand(points[0],modifiers);foreach(var p in points.Skip(1))MoveVectorFreehand(p);FinishVectorFreehand(points.Last());}
 public void TestArc(List<PointF> points){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,(int)points[0].X,(int)points[0].Y,0));arcStroke=true;foreach(var p in points.Skip(1))OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,(int)p.X,(int)p.Y,0));var end=points.Last();OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,(int)end.X,(int)end.Y,0));}
}
partial class Studio {
 public void TestVersion28(){var arc=new List<PointF>();for(int i=0;i<=90;i++){double a=i*Math.PI/90;arc.Add(new PointF(250+(float)Math.Cos(a)*100,200+(float)Math.Sin(a)*100+(float)Math.Sin(i*2)*1.5f));}var fitted=ArcAssist.Fit(arc);if(fitted==null||fitted[0]!=arc[0]||fitted.Last()!=arc.Last())throw new Exception("Arc fit/endpoints");foreach(var p in fitted)if(Math.Abs(StrokeSession.Distance(p,new PointF(250,200))-100)>3)throw new Exception("Arc accuracy");arc.Reverse();if(ArcAssist.Fit(arc)==null)throw new Exception("Reverse arc");if(ArcAssist.Fit(Enumerable.Range(0,20).Select(i=>new PointF(i*5,100)).ToList())!=null)throw new Exception("Reject straight arc");SetDocument(new Document("A4",100),null);SelectTool("Pen");canvas.Zoom=1;canvas.Offset=PointF.Empty;canvas.BrushSize=8;canvas.PressureMode="No pressure";int history=undo.Count;canvas.TestArc(arc);if(undo.Count!=history+1||canvas.Doc.Selected.Image.GetPixel(250,300).A==0)throw new Exception("Pixel arc/undo");Travel(undo,redo);if(canvas.Doc.Selected.Image.GetPixel(250,300).A!=0)throw new Exception("Arc undo");AddTypedLayer(true);vectorButtons["Freehand"].PerformClick();foreach(var key in new[]{Keys.None,Keys.Alt,Keys.Shift,Keys.Control}){canvas.TestFreehand(key==Keys.Control?EllipseSamples(100,60,.6,true):arc,key);var shape=canvas.Doc.Selected.Vectors.Last();if(shape.Points.Count<2||shape.Points.Count>=arc.Count)throw new Exception("Compact editable vector");if(key==Keys.Control&&shape.Kind!="Ellipse"||key==Keys.Shift&&shape.Kind!="Line")throw new Exception("Vector modifiers");canvas.TestDraftPaint();}int count=canvas.Doc.Selected.Vectors.Count;Travel(undo,redo);if(canvas.Doc.Selected.Vectors.Count!=count-1)throw new Exception("Freehand undo");Travel(redo,undo);string file=System.IO.Path.Combine(System.IO.Path.GetTempPath(),Guid.NewGuid()+".idsk");try{canvas.Doc.Save(file);using(var loaded=Document.Load(file))if(loaded.Selected.Vectors.Count!=count)throw new Exception("Freehand persistence");}finally{if(System.IO.File.Exists(file))System.IO.File.Delete(file);}dirty=false;}
}
}
